import React from 'react';
import { Helmet } from 'react-helmet';
import { useStaticQuery, graphql } from 'gatsby';
import { useI18next } from 'gatsby-plugin-react-i18next';

function SEO({ title, description, image, article, lang, path }) {
  const { site } = useStaticQuery(
    graphql`
      query {
        site {
          siteMetadata {
            title
            description
            author
            siteUrl
            keywords
          }
        }
      }
    `
  );

  const { language, languages } = useI18next();
  const currentLang = lang || language;

  const metaDescription = description || site.siteMetadata.description;
  const metaTitle = title || site.siteMetadata.title;
  const fullTitle = title ? `${title} | ${site.siteMetadata.title}` : site.siteMetadata.title;
  const metaImage = image || `${site.siteMetadata.siteUrl}/og-image.png`;
  const canonicalUrl = path
    ? `${site.siteMetadata.siteUrl}${currentLang === 'en-us' ? '' : `/${currentLang}`}${path}`
    : site.siteMetadata.siteUrl;

  return (
    <Helmet
      htmlAttributes={{
        lang: currentLang,
      }}
      title={fullTitle}
      meta={[
        {
          name: `description`,
          content: metaDescription,
        },
        {
          name: `keywords`,
          content: site.siteMetadata.keywords.join(', '),
        },
        {
          property: `og:title`,
          content: metaTitle,
        },
        {
          property: `og:description`,
          content: metaDescription,
        },
        {
          property: `og:type`,
          content: article ? `article` : `website`,
        },
        {
          property: `og:url`,
          content: canonicalUrl,
        },
        {
          property: `og:image`,
          content: metaImage,
        },
        {
          property: `og:image:alt`,
          content: metaTitle,
        },
        {
          property: `og:locale`,
          content: currentLang.replace('-', '_'),
        },
        {
          name: `twitter:card`,
          content: `summary_large_image`,
        },
        {
          name: `twitter:creator`,
          content: site.siteMetadata.author,
        },
        {
          name: `twitter:title`,
          content: metaTitle,
        },
        {
          name: `twitter:description`,
          content: metaDescription,
        },
        {
          name: `twitter:image`,
          content: metaImage,
        },
      ]}
    >
      {/* Canonical URL */}
      <link rel="canonical" href={canonicalUrl} />

      {/* Alternate hreflang tags for multi-language */}
      {languages.map((lang) => (
        <link
          key={lang}
          rel="alternate"
          hrefLang={lang}
          href={`${site.siteMetadata.siteUrl}${lang === 'en-us' ? '' : `/${lang}`}${path || ''}`}
        />
      ))}

      {/* Default language */}
      <link
        rel="alternate"
        hrefLang="x-default"
        href={`${site.siteMetadata.siteUrl}${path || ''}`}
      />
    </Helmet>
  );
}

export default SEO;
