import { createGlobalStyle } from 'styled-components';

const GlobalStyle = createGlobalStyle`
  /* Import fonts */
  @import url('https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700;800&family=Jost:wght@300;400;500;600;700;800&family=JetBrains+Mono:wght@400;500;600&display=swap');

  /* Import KaTeX CSS for math typesetting */
  @import url('https://cdn.jsdelivr.net/npm/katex@0.16.9/dist/katex.min.css');

  /* CSS Reset */
  *, *::before, *::after {
    box-sizing: border-box;
    margin: 0;
    padding: 0;
  }

  /* Root variables for theme switching */
  :root {
    --color-bg: ${props => props.theme.colors.dark.bg};
    --color-bg-secondary: ${props => props.theme.colors.dark.bgSecondary};
    --color-text: ${props => props.theme.colors.dark.text};
    --color-text-secondary: ${props => props.theme.colors.dark.textSecondary};
    --color-surface: ${props => props.theme.colors.dark.surface};
    --color-border: ${props => props.theme.colors.dark.border};
    --color-primary: ${props => props.theme.colors.primary};
    --color-secondary: ${props => props.theme.colors.secondary};
    --color-accent: ${props => props.theme.colors.accent};
    --color-bg-rgb: 10, 14, 39;
  }

  /* Light mode */
  [data-theme='light'] {
    --color-bg: ${props => props.theme.colors.light.bg};
    --color-bg-secondary: ${props => props.theme.colors.light.bgSecondary};
    --color-text: ${props => props.theme.colors.light.text};
    --color-text-secondary: ${props => props.theme.colors.light.textSecondary};
    --color-surface: ${props => props.theme.colors.light.surface};
    --color-border: ${props => props.theme.colors.light.border};
    --color-bg-rgb: 255, 255, 255;
  }

  /* Base HTML */
  html {
    font-size: 16px;
    scroll-behavior: auto; /* Lenis will handle smooth scroll */
    -webkit-font-smoothing: antialiased;
    -moz-osx-font-smoothing: grayscale;
    text-rendering: optimizeLegibility;
  }

  /* Body */
  body {
    margin: 0;
    padding: 0;
    font-family: ${props => props.theme.typography.fonts.body};
    font-size: ${props => props.theme.typography.fontSizes.base};
    font-weight: ${props => props.theme.typography.fontWeights.normal};
    line-height: ${props => props.theme.typography.lineHeights.normal};
    color: var(--color-text);
    background-color: var(--color-bg);
    overflow-x: hidden;
    transition: background-color 0.3s ${props => props.theme.animations.easing.smooth},
                color 0.3s ${props => props.theme.animations.easing.smooth};
  }

  /* Typography */
  h1, h2, h3, h4, h5, h6 {
    font-family: ${props => props.theme.typography.fonts.heading};
    font-weight: ${props => props.theme.typography.fontWeights.bold};
    line-height: ${props => props.theme.typography.lineHeights.tight};
    color: var(--color-text);
    margin: 0;
  }

  h1 {
    font-size: ${props => props.theme.typography.fontSizes['6xl']};
    letter-spacing: ${props => props.theme.typography.letterSpacings.tight};

    @media (max-width: ${props => props.theme.breakpoints.md}) {
      font-size: ${props => props.theme.typography.fontSizes['4xl']};
    }
  }

  h2 {
    font-size: ${props => props.theme.typography.fontSizes['4xl']};

    @media (max-width: ${props => props.theme.breakpoints.md}) {
      font-size: ${props => props.theme.typography.fontSizes['3xl']};
    }
  }

  h3 {
    font-size: ${props => props.theme.typography.fontSizes['3xl']};

    @media (max-width: ${props => props.theme.breakpoints.md}) {
      font-size: ${props => props.theme.typography.fontSizes['2xl']};
    }
  }

  h4 {
    font-size: ${props => props.theme.typography.fontSizes['2xl']};
  }

  h5 {
    font-size: ${props => props.theme.typography.fontSizes.xl};
  }

  h6 {
    font-size: ${props => props.theme.typography.fontSizes.lg};
  }

  p {
    margin: 0 0 ${props => props.theme.space[4]} 0;
    line-height: ${props => props.theme.typography.lineHeights.relaxed};
    color: var(--color-text);
  }

  /* Links */
  a {
    color: ${props => props.theme.colors.primary};
    text-decoration: none;
    transition: color 0.2s ${props => props.theme.animations.easing.smooth};
    cursor: pointer;

    &:hover {
      color: ${props => props.theme.colors.accent};
    }

    &:focus-visible {
      outline: 2px solid ${props => props.theme.colors.primary};
      outline-offset: 2px;
      border-radius: 2px;
    }
  }

  /* Lists */
  ul, ol {
    margin: 0 0 ${props => props.theme.space[4]} 0;
    padding-left: ${props => props.theme.space[6]};
  }

  li {
    margin-bottom: ${props => props.theme.space[2]};
    line-height: ${props => props.theme.typography.lineHeights.relaxed};
  }

  /* Code */
  code, pre {
    font-family: ${props => props.theme.typography.fonts.mono};
  }

  code {
    background-color: var(--color-surface);
    padding: 0.125rem 0.375rem;
    border-radius: ${props => props.theme.radii.sm};
    font-size: 0.875em;
    color: ${props => props.theme.colors.accent};
  }

  pre {
    background-color: var(--color-surface);
    padding: ${props => props.theme.space[4]};
    border-radius: ${props => props.theme.radii.md};
    overflow-x: auto;
    margin-bottom: ${props => props.theme.space[4]};
    border: 1px solid var(--color-border);

    code {
      background-color: transparent;
      padding: 0;
      border-radius: 0;
      color: var(--color-text);
    }
  }

  /* Blockquotes */
  blockquote {
    margin: ${props => props.theme.space[6]} 0;
    padding: ${props => props.theme.space[4]} ${props => props.theme.space[6]};
    border-left: 4px solid ${props => props.theme.colors.primary};
    background-color: var(--color-surface);
    border-radius: ${props => props.theme.radii.md};
    font-style: italic;
    color: var(--color-text-secondary);

    p:last-child {
      margin-bottom: 0;
    }
  }

  /* Images */
  img {
    max-width: 100%;
    height: auto;
    display: block;
  }

  /* Horizontal rule */
  hr {
    border: 0;
    height: 1px;
    background-color: var(--color-border);
    margin: ${props => props.theme.space[8]} 0;
  }

  /* Tables */
  table {
    width: 100%;
    border-collapse: collapse;
    margin-bottom: ${props => props.theme.space[6]};
  }

  th, td {
    padding: ${props => props.theme.space[3]};
    text-align: left;
    border-bottom: 1px solid var(--color-border);
  }

  th {
    font-weight: ${props => props.theme.typography.fontWeights.semibold};
    background-color: var(--color-surface);
  }

  /* Form elements */
  input, textarea, select, button {
    font-family: inherit;
    font-size: inherit;
    line-height: inherit;
  }

  button {
    cursor: pointer;
    border: none;
    background: none;
    padding: 0;
    color: inherit;
  }

  /* Selection */
  ::selection {
    background-color: ${props => props.theme.colors.primary};
    color: ${props => props.theme.colors.dark.bg};
  }

  ::-moz-selection {
    background-color: ${props => props.theme.colors.primary};
    color: ${props => props.theme.colors.dark.bg};
  }

  /* Scrollbar styling (webkit browsers) */
  ::-webkit-scrollbar {
    width: 12px;
    height: 12px;
  }

  ::-webkit-scrollbar-track {
    background: var(--color-bg);
  }

  ::-webkit-scrollbar-thumb {
    background: ${props => props.theme.colors.primary};
    border-radius: ${props => props.theme.radii.full};
    border: 3px solid var(--color-bg);

    &:hover {
      background: ${props => props.theme.colors.accent};
    }
  }

  /* Firefox scrollbar */
  * {
    scrollbar-width: thin;
    scrollbar-color: ${props => props.theme.colors.primary} var(--color-bg);
  }

  /* Accessibility */
  .sr-only {
    position: absolute;
    width: 1px;
    height: 1px;
    padding: 0;
    margin: -1px;
    overflow: hidden;
    clip: rect(0, 0, 0, 0);
    white-space: nowrap;
    border-width: 0;
  }

  /* Focus visible (keyboard navigation) */
  *:focus-visible {
    outline: 2px solid ${props => props.theme.colors.primary};
    outline-offset: 2px;
  }

  /* Remove focus outline for mouse users */
  *:focus:not(:focus-visible) {
    outline: none;
  }

  /* Disable animations for users who prefer reduced motion */
  @media (prefers-reduced-motion: reduce) {
    *,
    *::before,
    *::after {
      animation-duration: 0.01ms !important;
      animation-iteration-count: 1 !important;
      transition-duration: 0.01ms !important;
      scroll-behavior: auto !important;
    }
  }

  /* Print styles */
  @media print {
    body {
      background-color: white;
      color: black;
    }

    a {
      text-decoration: underline;
    }

    nav, aside, footer {
      display: none;
    }
  }
`;

export default GlobalStyle;
