import React, { useState, useEffect } from 'react';
import { Link, navigate } from 'gatsby';
import { useTranslation, useI18next } from 'gatsby-plugin-react-i18next';
import styled from 'styled-components';

const HeaderWrapper = styled.header`
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: ${props => props.theme.zIndices.sticky};
  background-color: ${props => props.scrolled
    ? 'rgba(var(--color-bg-rgb), 0.9)'
    : 'transparent'};
  backdrop-filter: ${props => props.scrolled ? 'blur(12px)' : 'none'};
  border-bottom: 1px solid ${props => props.scrolled
    ? 'var(--color-border)'
    : 'transparent'};
  transition: all 0.3s ${props => props.theme.animations.easing.smooth};
`;

const Nav = styled.nav`
  max-width: ${props => props.theme.containers.xl};
  margin: 0 auto;
  padding: ${props => props.theme.space[4]} ${props => props.theme.space[6]};
  display: flex;
  justify-content: space-between;
  align-items: center;
`;

const Logo = styled(Link)`
  font-family: ${props => props.theme.typography.fonts.heading};
  font-size: ${props => props.theme.typography.fontSizes['2xl']};
  font-weight: ${props => props.theme.typography.fontWeights.bold};
  color: var(--color-text);
  letter-spacing: ${props => props.theme.typography.letterSpacings.tight};
  transition: color 0.3s ${props => props.theme.animations.easing.smooth};

  &:hover {
    color: ${props => props.theme.colors.primary};
  }
`;

const NavLinks = styled.div`
  display: flex;
  align-items: center;
  gap: ${props => props.theme.space[6]};

  @media (max-width: ${props => props.theme.breakpoints.md}) {
    display: ${props => props.mobileOpen ? 'flex' : 'none'};
    position: fixed;
    top: 70px;
    left: 0;
    right: 0;
    background-color: var(--color-surface);
    flex-direction: column;
    padding: ${props => props.theme.space[6]};
    border-bottom: 1px solid var(--color-border);
    backdrop-filter: blur(12px);
  }
`;

const NavLink = styled(Link)`
  font-family: ${props => props.theme.typography.fonts.body};
  font-size: ${props => props.theme.typography.fontSizes.base};
  font-weight: ${props => props.theme.typography.fontWeights.medium};
  color: var(--color-text);
  position: relative;
  transition: color 0.3s ${props => props.theme.animations.easing.smooth};

  &::after {
    content: '';
    position: absolute;
    bottom: -4px;
    left: 0;
    right: 0;
    height: 2px;
    background-color: ${props => props.theme.colors.primary};
    transform: scaleX(0);
    transition: transform 0.3s ${props => props.theme.animations.easing.smooth};
  }

  &:hover {
    color: ${props => props.theme.colors.primary};

    &::after {
      transform: scaleX(1);
    }
  }

  &.active {
    color: ${props => props.theme.colors.primary};

    &::after {
      transform: scaleX(1);
    }
  }
`;

const LanguageSwitcher = styled.div`
  display: flex;
  gap: ${props => props.theme.space[2]};
`;

const LangButton = styled.button`
  font-family: ${props => props.theme.typography.fonts.mono};
  font-size: ${props => props.theme.typography.fontSizes.sm};
  font-weight: ${props => props.theme.typography.fontWeights.medium};
  color: ${props => props.active ? props.theme.colors.primary : 'var(--color-text-secondary)'};
  padding: ${props => props.theme.space[2]} ${props => props.theme.space[3]};
  border: 1px solid ${props => props.active ? props.theme.colors.primary : 'var(--color-border)'};
  border-radius: ${props => props.theme.radii.md};
  background-color: ${props => props.active ? 'rgba(255, 107, 53, 0.1)' : 'transparent'};
  cursor: pointer;
  transition: all 0.3s ${props => props.theme.animations.easing.smooth};
  text-transform: uppercase;

  &:hover {
    color: ${props => props.theme.colors.primary};
    border-color: ${props => props.theme.colors.primary};
    background-color: rgba(255, 107, 53, 0.1);
  }
`;

const MobileMenuButton = styled.button`
  display: none;
  flex-direction: column;
  gap: 4px;
  background: transparent;
  border: none;
  cursor: pointer;
  padding: ${props => props.theme.space[2]};

  @media (max-width: ${props => props.theme.breakpoints.md}) {
    display: flex;
  }

  span {
    width: 24px;
    height: 2px;
    background-color: var(--color-text);
    transition: all 0.3s ${props => props.theme.animations.easing.smooth};

    &:nth-child(1) {
      transform: ${props => props.isOpen ? 'rotate(45deg) translateY(6px)' : 'none'};
    }

    &:nth-child(2) {
      opacity: ${props => props.isOpen ? 0 : 1};
    }

    &:nth-child(3) {
      transform: ${props => props.isOpen ? 'rotate(-45deg) translateY(-6px)' : 'none'};
    }
  }
`;

const ThemeToggle = styled.button`
  background: transparent;
  border: 1px solid var(--color-border);
  border-radius: ${props => props.theme.radii.full};
  width: 40px;
  height: 40px;
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  color: var(--color-text);
  font-size: ${props => props.theme.typography.fontSizes.xl};
  transition: all 0.3s ${props => props.theme.animations.easing.smooth};
  margin-left: ${props => props.theme.space[4]};

  &:hover {
    border-color: ${props => props.theme.colors.primary};
    color: ${props => props.theme.colors.primary};
    background: rgba(255, 107, 53, 0.1);
  }

  @media (max-width: ${props => props.theme.breakpoints.md}) {
    margin-left: 0;
  }
`;

const DesktopActions = styled.div`
  display: flex;
  align-items: center;
  gap: ${props => props.theme.space[4]};
`;

const MobileActions = styled.div`
  display: flex;
  align-items: center;
  gap: ${props => props.theme.space[3]};

  @media (min-width: ${props => props.theme.breakpoints.md}) {
    display: none;
  }
`;

function Header({ isDarkMode, toggleTheme }) {
  const { t } = useTranslation();
  const { language } = useI18next();
  const [scrolled, setScrolled] = useState(false);
  const [mobileOpen, setMobileOpen] = useState(false);

  useEffect(() => {
    const handleScroll = () => {
      setScrolled(window.scrollY > 50);
    };

    window.addEventListener('scroll', handleScroll);
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  const handleLanguageChange = (lang) => {
    if (lang === language) return;
    if (typeof window === 'undefined') return;

    // Get current path without language prefix
    const currentPath = window.location.pathname;
    const pathWithoutLang = currentPath.replace(/^\/(es-mx|en-us)/, '');

    // Navigate to the same page in the new language
    const newPath = lang === 'en-us' ? pathWithoutLang || '/' : `/${lang}${pathWithoutLang || '/'}`;
    navigate(newPath);
  };

  const navItems = [
    { key: 'projects', path: '/projects' },
    { key: 'publications', path: '/publications' },
    { key: 'blog', path: '/blog' },
    { key: 'teaching', path: '/teaching' },
    { key: 'people', path: '/people' },
    { key: 'books', path: '/books' },
    { key: 'cv', path: '/cv' },
  ];

  return (
    <HeaderWrapper scrolled={scrolled}>
      <Nav>
        <Logo to="/">
          {t('nav.logo', 'Ollin D. Langle-Chimal')}
        </Logo>

        <NavLinks mobileOpen={mobileOpen}>
          {navItems.map(item => (
            <NavLink
              key={item.key}
              to={item.path}
              activeClassName="active"
              onClick={() => setMobileOpen(false)}
            >
              {t(`nav.${item.key}`, item.key)}
            </NavLink>
          ))}

          <LanguageSwitcher>
            <LangButton
              active={language === 'en-us'}
              onClick={() => handleLanguageChange('en-us')}
              aria-label="Switch to English"
            >
              EN
            </LangButton>
            <LangButton
              active={language === 'es-mx'}
              onClick={() => handleLanguageChange('es-mx')}
              aria-label="Cambiar a Español"
            >
              ES
            </LangButton>
          </LanguageSwitcher>
        </NavLinks>

        <DesktopActions>
          <ThemeToggle
            onClick={toggleTheme}
            aria-label={isDarkMode ? 'Switch to light mode' : 'Switch to dark mode'}
          >
            {isDarkMode ? '☀️' : '🌙'}
          </ThemeToggle>
        </DesktopActions>

        <MobileActions>
          <ThemeToggle
            onClick={toggleTheme}
            aria-label={isDarkMode ? 'Switch to light mode' : 'Switch to dark mode'}
          >
            {isDarkMode ? '☀️' : '🌙'}
          </ThemeToggle>

          <MobileMenuButton
            isOpen={mobileOpen}
            onClick={() => setMobileOpen(!mobileOpen)}
            aria-label="Toggle mobile menu"
          >
            <span />
            <span />
            <span />
          </MobileMenuButton>
        </MobileActions>
      </Nav>
    </HeaderWrapper>
  );
}

export default Header;
